import { unstable_cache } from 'next/cache';
import fs from 'fs/promises';
import path from 'path';

const DB_PATH = path.join(process.cwd(), 'lib/db.json');

export type Product = {
  id: string;
  name: string;
  price: number;
  stock: number;
  lastUpdated: string;
};

async function fetchProductsFromSource(): Promise<Product[]> {
  // Simulate slow external API/database read
  await new Promise((resolve) => setTimeout(resolve, 1000));

  try {
    const data = await fs.readFile(DB_PATH, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    console.error('Failed to read products:', error);
    return [];
  }
}

// Cached version of the product fetch
export const getProducts = unstable_cache(
  async () => {
    return fetchProductsFromSource();
  },
  ['products-cache-key'], // keyParts
  { tags: ['products'], revalidate: 3600 } // options
);

export async function updateProductData() {
  // Simulate fetching new data from upstream ERP
  await new Promise((resolve) => setTimeout(resolve, 2000));

  const newProducts: Product[] = [
    { 
      id: "1", 
      name: "Laptop Pro", 
      price: 1299 + Math.floor(Math.random() * 100), 
      stock: Math.floor(Math.random() * 50), 
      lastUpdated: new Date().toISOString() 
    },
    { 
      id: "2", 
      name: "Smartphone X", 
      price: 799 + Math.floor(Math.random() * 50), 
      stock: Math.floor(Math.random() * 100), 
      lastUpdated: new Date().toISOString() 
    },
    { 
      id: "3", 
      name: "Wireless Headphones", 
      price: 249 + Math.floor(Math.random() * 30), 
      stock: Math.floor(Math.random() * 200), 
      lastUpdated: new Date().toISOString() 
    },
    {
      id: "4",
      name: "New Tablet",
      price: 499,
      stock: 30,
      lastUpdated: new Date().toISOString()
    }
  ];

  await fs.writeFile(DB_PATH, JSON.stringify(newProducts, null, 2));
  return newProducts;
}

import { getProducts, updateProductData } from '@/lib/products';
import { revalidateTag } from 'next/cache';
import { Suspense } from 'react';

export default async function Page() {
  const products = await getProducts();
  const lastSync = products.length > 0 ? products[0].lastUpdated : 'Never';

  async function syncCatalog() {
    'use server';

    // In a real-world scenario, this might trigger a background job queue.
    // Here, we simulate a background process that updates the data and then revalidates.
    // We do NOT await this, so the user gets immediate feedback.
    // Note: In serverless (Lambda/Vercel), this background work might be cut off 
    // without "waitUntil" or similar, but for this persistent server demo it works.

    (async () => {
        try {
            console.log("Starting background sync...");
            await updateProductData();
            console.log("Background sync complete. Revalidating...");
            revalidateTag('products'); 
        } catch (err) {
            console.error("Background sync failed", err);
        }
    })();

    // We could also revalidate immediately if we just wanted to trigger a refetch,
    // but here we want to revalidate *after* the data is updated.
    // However, since we return immediately, the page won't reflect changes yet.
  }

  return (
    <div className="p-8 font-sans">
      <h1 className="text-2xl font-bold mb-4">Product Catalog Admin</h1>

      <div className="mb-6 p-4 bg-gray-100 rounded flex justify-between items-center">
        <div>
          <p className="text-sm text-gray-600">Last Catalog Sync:</p>
          <p className="font-mono font-bold">{lastSync}</p>
        </div>

        <form action={syncCatalog}>
          <button 
            type="submit"
            className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition-colors"
          >
            Sync Latest Catalog
          </button>
        </form>
      </div>

      <div className="border rounded-lg overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50">
            <tr>
              <th className="p-4 border-b">ID</th>
              <th className="p-4 border-b">Name</th>
              <th className="p-4 border-b">Price</th>
              <th className="p-4 border-b">Stock</th>
            </tr>
          </thead>
          <tbody>
            <Suspense fallback={<tr><td colSpan={4} className="p-4 text-center">Loading products...</td></tr>}>
                {products.map((product) => (
                <tr key={product.id} className="hover:bg-gray-50">
                    <td className="p-4 border-b font-mono text-sm">{product.id}</td>
                    <td className="p-4 border-b">{product.name}</td>
                    <td className="p-4 border-b">${product.price}</td>
                    <td className="p-4 border-b">
                        <span className={`px-2 py-1 rounded text-xs ${product.stock < 20 ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'}`}>
                            {product.stock} units
                        </span>
                    </td>
                </tr>
                ))}
            </Suspense>
            {products.length === 0 && (
                <tr>
                    <td colSpan={4} className="p-4 text-center text-gray-500">No products found.</td>
                </tr>
            )}
          </tbody>
        </table>
      </div>

      <p className="mt-4 text-xs text-gray-400">
        Data is cached via tag "products". Sync triggers background refresh.
      </p>
    </div>
  );
}

